{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@kitlangton/opencode-session-recap",
  "version": "0.1.2",
  "description": "Transient session recaps for the OpenCode V2 TUI",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/kitlangton/opencode-plugins.git",
    "directory": "packages/session-recap"
  },
  "homepage": "https://github.com/kitlangton/opencode-plugins/tree/main/packages/session-recap",
  "bugs": "https://github.com/kitlangton/opencode-plugins/issues",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "recap"
  ],
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist",
    "README.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "bun ../../scripts/build.ts .",
    "check": "bun run typecheck && bun run test",
    "prepack": "bun run build",
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "dependencies": {
    "@opencode-ai/plugin": "0.0.0-next-17271",
    "@opentui/core": "0.0.0-20260808-9ecf7c0a",
    "solid-js": "1.9.14"
  },
  "devDependencies": {
    "@tsconfig/bun": "1.0.9",
    "@opentui/solid": "0.5.1"
  }
}
